pub fn count_by_kind(kind: &str) -> usize {
    let mut n = 0usize;
    let mut i = 0usize;
    while i < DOMAIN_TABLE.len() {
        if DOMAIN_TABLE[i].kind.as_bytes() == kind.as_bytes() {
            n += 1;
        }
        i += 1;
    }
    n
}

